preferences.tsx.content:
export function Preferences({enabled, saving, save, setEnabled, error, done}) {
  return <main aria-label="Preferences">
    <label><input type="checkbox" checked={enabled} onChange={e => setEnabled(e.target.checked)} />Email notices</label>
    <button disabled={saving} onClick={save}>{saving ? "Saving…" : "Apply changes"}</button>
    {error && <p role="alert">Save failed</p>}
    {done && <p role="status">Preferences updated</p>}
  </main>;
}

